import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    rounds = []
    idx = 1
    for _ in range(n):
        name = data[idx]
        score = int(data[idx + 1])
        idx += 2
        rounds.append((name, score))

    final_scores = {}
    for name, score in rounds:
        if name not in final_scores:
            final_scores[name] = 0
        final_scores[name] += score

    max_score = max(final_scores.values())

    candidates = [name for name, score in final_scores.items() if score == max_score]

    current_scores = {}
    for name, score in rounds:
        if current_scores.get(name, 0) + score >= max_score:
            if name in candidates:
                print(name)
                return
        current_scores[name] = current_scores.get(name, 0) + score

if __name__ == "__main__":
    main()
